/* Willowwood is a neighborhood, with private furnished homes off a side lane. */
(()=>{'use strict';
const homes=[{id:'pipHome',person:'Pip',friend:'pip',name:'Pip’s Cottage',image:'neighbor-pip',about:'Patchwork cushions, a tea table, and family keepsakes fill Pip’s friendly little home.',welcome:'I hoped you would follow the lane. There is always room for a neighbor at my table.'},{id:'fernHome',person:'Fern',friend:'fern',name:'Fern’s Baker’s Cottage',image:'neighbor-fern',about:'Fern’s own hearth, bread board, supper table and rocking chair make this a home beyond the tavern and bakery.',welcome:'The bakery has its busy hours. Here I like a little bread, a little tea, and good company.'},{id:'cobbleHome',person:'Master Cobble',friend:'cobble',name:'Master Cobble’s Home',image:'neighbor-cobble',about:'Worn leather chairs, books, a warm hearth and a personal sewing basket sit beyond the public workshop.',welcome:'Even a shoemaker needs somewhere to put his feet up. Come in and tell me about your day.'},{id:'willowHome',person:'Keeper Willow',friend:'willow',name:'Keeper Willow’s Cottage',image:'neighbor-willow',about:'Plants frame the windows around Willow’s comfortable chair, books, tea table and sleeping nook.',welcome:'The garden follows me indoors a little. Sit by the window; the kettle is ready.'}];
function ensure(s){if(!s.cityNeighborhood||typeof s.cityNeighborhood!=='object'||Array.isArray(s.cityNeighborhood))s.cityNeighborhood={};const n=s.cityNeighborhood;for(const key of ['visits','moments'])if(!n[key]||typeof n[key]!=='object'||Array.isArray(n[key]))n[key]={};return n}
function home(id){return homes.find(h=>h.id===id)}
function at(id,w){return !!home(id)&&w?.district==='home'&&w.room===id&&!w.porch}
function visit(s,id,w){if(!at(id,w))return false;const n=ensure(s);n.visits[id]=(n.visits[id]||0)+1;return true}
function present(id,c){return id==='pipHome'||c.hour<9||c.hour>=17}
function moment(s,id,kind,w,c){const h=home(id);if(!h||!at(id,w)||!['greet','tea','gift'].includes(kind))return{ok:false,reason:'Visit this neighbor’s home first.'};const n=ensure(s),key=c.key+':'+id+':'+kind;if(n.moments[key])return{ok:false,reason:'You have shared this neighborly moment today. Come by again tomorrow.'};const L=globalThis.EldoriaLifeModel,l=L.ensure(s);if(kind==='gift'){if(!(l.bag.flowers>0)){if(globalThis.EldoriaPromiseModel?.active(s))l.bag.flowers=1;else return{ok:false,reason:'Bring one flower material from gardening or work to leave a bouquet.'}}l.bag.flowers--;}n.moments[key]=true;const points=kind==='gift'?2:1;l.friends[h.friend]=(l.friends[h.friend]||0)+points;L.stats(s).talks++;const isPresent=present(id,c);return{ok:true,title:kind==='greet'?(isPresent?'A warm welcome from '+h.person:'A friendly reply left for '+h.person):kind==='tea'?(isPresent?'A pot of tea shared with '+h.person:'A tea invitation left for '+h.person):'A little bouquet for '+h.person,detail:isPresent?'Your neighbor remembers the visit.':'Your note waits beside the door while your neighbor is out. Your kindness will be remembered.'}}
globalThis.EldoriaNeighborhoodModel={homes,ensure,home,at,visit,present,moment};
})();
